// Modelo (no es una medición): 1 segundo de animación a 60 Hz. Cada 16,67 ms el sistema pide un cuadro nuevo.
const hz = 60, paso = 1000 / hz, cuadrosEnUnSegundo = 60;
// JavaScript queda ocupado entre t = 300 ms y t = 420 ms (por ejemplo, armando una pantalla pesada)
const ocupado = { desde: 300, hasta: 420 };
function contar(calculaJS) {
  let salen = 0;
  for (let i = 1; i <= cuadrosEnUnSegundo; i++) {
    const t = i * paso;
    const jsOcupado = t >= ocupado.desde && t < ocupado.hasta;
    if (!(calculaJS && jsOcupado)) salen++;
  }
  return salen;
}
const jsPuro = contar(true), hiloUI = contar(false);
console.log("cuadros esperados en 1 s:", cuadrosEnUnSegundo);
console.log("calculados por el hilo de JS:", jsPuro, "(se pierden " + (cuadrosEnUnSegundo - jsPuro) + ")");
console.log("calculados por el hilo de UI:", hiloUI, "(se pierden " + (cuadrosEnUnSegundo - hiloUI) + ")");
console.log("");
for (const f of [60, 90, 120]) console.log(f + " Hz -> " + (1000 / f).toFixed(1) + " ms por cuadro");

// Una animación es una función del tiempo: posición = desde + (hasta - desde) * curva(t / duración)
const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);
const duracion = 270, paso = 1000 / 60, ancho = 390; // ms, ms por cuadro, ancho de pantalla en puntos
const filas = [];
for (let i = 0; i * paso <= duracion + paso; i++) {
  const x = Math.min(1, (i * paso) / duracion);
  filas.push(i + ": " + Math.round(ancho * easeOutCubic(x)));
}
console.log(filas.length + " cuadros para 270 ms a 60 Hz (el último ya no se mueve)");
console.log(filas.slice(0, 8).join("  |  "));
console.log("...");
console.log(filas.slice(-3).join("  |  "));
